import pandas as pd, numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
imp = pd.read_csv('data/impressions.csv'); conv = pd.read_csv('data/conversions.csv')
test = pd.read_csv('data/test_contexts.csv')
T_ref = imp.timestamp.max(); age=(T_ref-imp.timestamp)/3600.0
d=conv.delay_hours.values; ln=np.log(d); mu,sig=ln.mean(),ln.std(ddof=0)
F = stats.norm.cdf((np.log(np.clip(age,1e-4,None))-mu)/sig)
m = imp.merge(conv[['impression_id','conversion_value']], on='impression_id', how='left')
m['conv']=m.impression_id.isin(conv.impression_id).astype(int); m['F']=F
SEG={'young':0,'middle':1,'senior':2}; DEV={'mobile':0,'desktop':1,'tablet':2}
SEGn={v:k for k,v in SEG.items()}; DEVn={v:k for k,v in DEV.items()}
arm_val = m[m.conv==1].groupby('arm_id').conversion_value.mean().reindex(range(10)).values
base = m.conv.sum()/m.F.sum()
def grp(cols, idx):
    g = m.groupby(cols).agg(c=('conv','sum'), Fsum=('F','sum'))
    r = (g.c/g.Fsum).to_numpy()
    return {k: r[i] for k,i in zip(g.index, range(len(g)))}
ah = grp(['arm_id','hour_of_day'], None)
dw_m = {k: v/base for k,v in grp(['day_of_week'],None).items()}
sg_m = {k: v/base for k,v in grp(['user_segment'],None).items()}
dv_m = {k: v/base for k,v in grp(['device_type'],None).items()}
Ht=test.hour_of_day.values; Dt=test.day_of_week.values
St=test.user_segment.values; Vt=test.device_type.values
TR = np.empty((len(test),10))
for a in range(10):
    for i in range(len(test)):
        TR[i,a] = ah[(a,Ht[i])]*dw_m[Dt[i]]*sg_m[St[i]]*dv_m[Vt[i]]*arm_val[a]
print('oracle (armhour x mults):', TR.max(0).mean())

rng = np.random.default_rng(0); folds = rng.integers(0,5,len(m))
def fit_model(tr, with_ah, C):
    A=m[tr].arm_id.values; H=m[tr].hour_of_day.values; D=m[tr].day_of_week.values
    S=m[tr].user_segment.map(SEG).values; V=m[tr].device_type.map(DEV).values
    P=[np.eye(10)[A], np.eye(24)[H], np.eye(7)[D], np.eye(3)[S], np.eye(3)[V]]
    if with_ah: P.append(np.eye(240)[A*24+H])
    X=np.column_stack(P).astype(np.float32)
    lr=LogisticRegression(C=C, solver='lbfgs', max_iter=10000)
    lr.fit(X, m[tr].conv.values, sample_weight=m[tr].F.values)
    return lr.coef_[0], float(lr.intercept_[0])
def policy_reward(b, ic, with_ah):
    zt = ic + b[10:34][Ht]+b[34:41][Dt]+b[41:44][test.user_segment.map(SEG).values]+b[44:47][test.device_type.map(DEV).values]
    ER=np.empty((len(test),10))
    for a in range(10):
        ER[:,a]=1/(1+np.exp(-(zt+b[a]+(b[47:][a*24+Ht] if with_ah else 0))))*arm_val[a]
    sel=ER.argmax(axis=1)
    return ER[np.arange(len(test)),sel]
for with_ah, C in [(True,1e6),(False,1e6),(True,1e3)]:
    rewards = np.mean([policy_reward(*fit_model(folds!=f, with_ah, C), with_ah) for f in range(5)], axis=0)
    print(f'with_ah={with_ah} C={C}: mine={rewards.mean():.4f} ratio={TR.max(0).mean()/rewards.mean():.4f}')
